fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let n = a.len();
    if n <= 1 {
        return (a, Vec::new());
    }

    // For n > 1, choose a split point strictly between 0 and n.
    let mid = n / 2; // ensures 1 <= mid <= n-1 when n > 1
    let mut a = a;
    let right = a.split_off(mid);
    (a, right)
}